import React, {useEffect,useState} from "react";
import {createRoot} from "react-dom/client";
import {connect,type EditorSession} from "@station/sdk";
import {Button,Surface,Stack,setIconOverrides} from "@station/ui";
const station=await connect();
station.theme.subscribe(theme=>setIconOverrides(theme.icons??{}));
const handle=await station.acquire<EditorSession>({id:"station:editor/session",version:"1.0.0"});
function Studio(){
 const [files,setFiles]=useState<Record<string,string>>({}),[path,setPath]=useState(""),[error,setError]=useState("");
 const load=async()=>{const next=await handle.value.files();setFiles(next);setPath(previous=>next[previous]!==undefined?previous:Object.keys(next).find(path=>path.endsWith(".svg"))??"")};
 useEffect(()=>{let disposed=false,stop:(()=>void)|undefined;void load();void handle.subscribe(()=>{if(!disposed)void load()}).then(unsubscribe=>{if(disposed)unsubscribe();else stop=unsubscribe});return()=>{disposed=true;stop?.()}},[]);
 useEffect(()=>{if(path)void handle.value.select(path)},[path]);
 const source=files[path]??"",url=source?"data:image/svg+xml,"+encodeURIComponent(source):"";
 const create=async()=>{if(files["icon.svg"]!==undefined)return;await handle.value.edit("icon.svg",'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><circle cx="12" cy="12" r="8" fill="#829b64"/></svg>');await handle.value.select("icon.svg");setPath("icon.svg");await load()};
 const recolor=async(value:string)=>{try{const doc=new DOMParser().parseFromString(source,"image/svg+xml");if(doc.querySelector("parsererror")||doc.documentElement.localName!=="svg")throw Error("Fix the SVG source first");doc.documentElement.setAttribute("stroke",value);await handle.value.edit(path,new XMLSerializer().serializeToString(doc.documentElement))}catch(error){setError(String(error))}};
 return <Surface style={{height:"100%",boxSizing:"border-box",padding:16}}><Stack gap={16}><Stack direction="row" style={{alignItems:"center",flexWrap:"wrap"}}><strong>SVG studio</strong><select aria-label="SVG file" value={path} onChange={event=>{setPath(event.target.value);void handle.value.select(event.target.value)}}>{Object.keys(files).filter(path=>path.endsWith(".svg")).map(path=><option key={path}>{path}</option>)}</select><Button onClick={()=>void create()} disabled={files["icon.svg"]!==undefined}>New SVG</Button></Stack>{source?<><div style={{minHeight:160,display:"grid",placeItems:"center",background:"#f4f4f0",borderRadius:12}}><img alt="SVG preview" src={url} style={{width:"min(240px,80%)",height:240}}/></div><label>Stroke <input aria-label="SVG stroke" type="color" onChange={event=>void recolor(event.target.value)}/></label></>:<p>Select or create an SVG file.</p>}<p style={{fontSize:12,opacity:.65}}>Edit shapes in the shared Code pane. Preview updates from this asset's editor session. SVG is displayed as an image, not inserted into the host DOM.</p>{error&&<p role="alert">{error}</p>}</Stack></Surface>;
}
createRoot(document.getElementById("app")!).render(<Studio/>);
